def weight_quantization_bits(precision):
    if precision <= 1.0:
        return 1.0
    if precision <= 2.0:
        return 2.0
    if precision <= 4.0:
        return 4.0
    if precision <= 8.0:
        return 8.0
    if precision <= 16.0:
        return 16.0
    return 32.0



def checkpoint_size_estimate(n_parameters, dtype_bits, include_optimizer):
    base = n_parameters * dtype_bits / 8.0
    if include_optimizer > 0.5:
        return base * 3.0  # weights + m + v in FP32
    return base



def delta_compression_ratio(delta_norm, weight_norm):
    if weight_norm <= 0.0:
        return 1.0
    return delta_norm / weight_norm



